#!/usr/bin/env bash
# W1 figures + RESULTS.md generator (publication outputs). No GPU.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing figures generator..."
decode "scripts/ntc_w1_figures.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Generate all figures + RESULTS.md (instant):"
echo "  python scripts/ntc_w1_figures.py \\"
echo "    --probes experiments/ntc/w1_math500_Qwen3-4B.json \\"
echo "    --probes experiments/ntc/w1_gsm8k_Qwen3-4B.json \\"
echo "    --probes experiments/ntc/w1_gpqa16k_Qwen3-4B.json \\"
echo "    --probes experiments/ntc/w1_math500_Qwen3-1.7B.json"